        sessions.push({ agent: adapter.agent, path: item.path, mtime: item.mtime, primitives: adapter.parse(item.path) });
50→      } catch {
        skipped[adapter.agent] = (skipped[adapter.agent] ?? 0) + 1;
      }
    }
  }
