import { homedir } from "os";
import { join } from "path";
import { parseSession } from "../session-parse.js";
import type { SessionAdapter, SessionListItem } from "./types.js";

/** Claude encodes cwd with a LEADING dash: /Users/x/p -> -Users-x-p */
