    if (!isKnownType && looksLikeDir) {
      targetPath = rawType;
      rawType = "patch";
    } else if (!isKnownType) {
      ui.fail(`Unknown bump type "${rawType}". Use patch | minor | major | 1.2.3`);
      return await exit(1);
    }

    return await runNonInteractive(rawType, targetPath, scope);
  },
});

